import { randomBytes } from 'node:crypto';
import type { Client } from 'pg';

// Guarded test DB only; DDL identifiers and the target ID are generated by the test.
export async function installDecisionFault(client: Client, orderId: number) {
  const name = `p08_fault_${randomBytes(8).toString('hex')}`;
  const sequence = `${name}_seq`;
  await client.query(`CREATE SEQUENCE "${sequence}"`);
  try {
    await client.query(`CREATE FUNCTION "${name}"() RETURNS trigger LANGUAGE plpgsql AS $$
      BEGIN
        IF NEW."orderId" = ${orderId} AND NEW."fromStatus" = 'pending' THEN
          IF NOT EXISTS (SELECT 1 FROM "Order" WHERE id = ${orderId} AND status = NEW."toStatus") THEN
            RAISE EXCEPTION 'Expected partial state update';
          END IF;
          PERFORM nextval('"${sequence}"');
          RAISE EXCEPTION 'private P08 history fault' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
      END $$`);
    await client.query(`CREATE TRIGGER "${name}" BEFORE INSERT ON "OrderStatusHistory" FOR EACH ROW EXECUTE FUNCTION "${name}"()`);
  } catch (error) {
    await client.query(`DROP FUNCTION IF EXISTS "${name}"()`);
    await client.query(`DROP SEQUENCE "${sequence}"`);
    throw error;
  }
  return {
    async called() { return (await client.query<{ is_called: boolean }>(`SELECT is_called FROM "${sequence}"`)).rows[0]!.is_called; },
    async remove() {
      await client.query(`DROP TRIGGER "${name}" ON "OrderStatusHistory"`);
      await client.query(`DROP FUNCTION "${name}"()`);
      await client.query(`DROP SEQUENCE "${sequence}"`);
    },
  };
}
